import pandas as pd
import numpy as np

DATASET_PATH = 'chunks_csv/moran_local_2022_ghg.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

df_ghg = pd.read_csv(DATASET_PATH)
df_adj = pd.read_csv(ADJACENCY_PATH)

# Create symmetric neighbor dictionary
neighbors_dict = {}
for _, row in df_adj.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighbors_dict:
        neighbors_dict[borough] = []
    neighbors_dict[borough].append(neighbor)
    if neighbor not in neighbors_dict:
        neighbors_dict[neighbor] = []
    neighbors_dict[neighbor].append(borough)

# Map boroughs to GHG values
borough_to_ghg = dict(zip(df_ghg['borough'], df_ghg['GHG_value']))

# Compute global statistics
X_bar = df_ghg['GHG_value'].mean()
s_squared = df_ghg['GHG_value'].var()

# Calculate Local Moran's I for each borough
results = []
for index, row in df_ghg.iterrows():
    borough = row['borough']
    xi = row['GHG_value']
    neighbors = neighbors_dict.get(borough, [])
    sum_neighbors = 0.0
    for neighbor in neighbors:
        if neighbor in borough_to_ghg:
            xj = borough_to_ghg[neighbor]
            sum_neighbors += (xj - X_bar)
    I_i = (xi - X_bar) * sum_neighbors / s_squared
    if I_i > 0:
        if xi > X_bar:
            category = 'HH'
        else:
            category = 'LL'
    else:
        category = None
    results.append({
        'borough': borough,
        'I_i': I_i,
        'category': category
    })

# Prepare final answer
final_answer = []
for r in results:
    if r['category'] == 'HH':
        final_answer.append(f"{r['borough']} (HH, statistical method={r['I_i']:.4f})")
    elif r['category'] == 'LL':
        final_answer.append(f"{r['borough']} (LL, statistical method={r['I_i']:.4f})")

if not final_answer:
    print("FINAL ANSWER: none")
else:
    print("FINAL ANSWER: " + ", ".join(final_answer))
